    test("sarscov2 - paired_end - bam - alignment basic isize") {

        when {
            params {
                module_args = '--tools alignment basic isize'
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true), // bam
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true), // bai
                    [], // error_vcf
                    [], // error_vcf_idx
                    [], // error_intervals
                    [], // gcbias_exclude_intervals
                    [], // hybcap_baits
                    [], // hybcap_targets
                    [], // rna_gene_model
                    [], // rna_ribosomal_intervals
                    []  // wgs_intervals
                ]
                input[1] = [[],[],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["pdf"])).match() }
            )
        }
    }

